package ama.worker;
import ama.contract.ExternalContracts.*;import ama.contract.TaskContracts.*;import ama.contract.MinutesContracts;import ama.task.*;import java.util.*;import java.util.concurrent.atomic.*;import java.time.*;import java.lang.reflect.Proxy;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
/** Session/cache lifetime only. Genuine original-execution recovery is verified with the local provider separately. */
class ExpiredObservationSessionTest {
 static final class Fixture implements AutoCloseable {
  final AtomicBoolean fail=new AtomicBoolean(true);final AtomicInteger begins=new AtomicInteger(),releases=new AtomicInteger(),sends=new AtomicInteger();final List<ExternalOperationPort.PreparedObservation> seen=new ArrayList<>();final ExternalOperationHeartbeat heartbeat;final ExternalExecutionSession session;
  Fixture(boolean reconciliation)throws Exception{var subject=new SubjectRef("MEETING",UUID.randomUUID().toString());var token=new OperationToken(UUID.randomUUID().toString(),UUID.randomUUID().toString(),1,1,"SESSION_TEST",Instant.now().plusSeconds(30),subject);var operations=(ExternalOperationPort)Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{ExternalOperationPort.class},(p,m,a)->switch(m.getName()){case "beginPrepared"->{begins.incrementAndGet();yield Optional.of(token);}case "renew"->true;case "releaseRecordedLookup"->{releases.incrementAndGet();yield null;}case "observePrepared","observePreparedFact","recoverPreparedFact"->{seen.add((ExternalOperationPort.PreparedObservation)a[1]);if(fail.get())throw MinutesContracts.fail(MinutesContracts.FailureCode.BUDGET_EXCEEDED);yield ObservationResult.APPLIED;}default->throw new AssertionError("Unexpected external operation "+m.getName());});var permits=(ModelPermitPool)Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{ModelPermitPool.class},(p,m,a)->{throw new AssertionError("No global permit settlement or acquisition expected");});heartbeat=new ExternalOperationHeartbeat(operations,1);if(reconciliation)session=ExternalExecutionSession.reconciliation(token,operations,permits,heartbeat,()->true);else{var spec=new TaskSpec("KNOWLEDGE_PUBLISH_V1","KNOWLEDGE_PUBLISH",subject,"a".repeat(64),new TypedRef("PUBLICATION",UUID.randomUUID().toString()),"b".repeat(64),1,0,0,3);session=new ExternalExecutionSession(new Object(),new TaskLease(UUID.randomUUID().toString(),1,"SESSION_TEST",Instant.now().plusSeconds(20),spec),operations,permits,heartbeat,null,()->true,()->true);assertTrue(session.begin(new ExternalOperationPort.PreparedRequest(){}));}}
  public void close(){session.close();heartbeat.close();}
 }
 @Test void expiredPreparedObservationDoesNotOccupyAnOrdinaryWorkerSlotForeverOrRegainSend()throws Exception{try(var f=new Fixture(false)){var observation=new ExternalOperationPort.PreparedObservation(){public boolean retainForLocalRetry(RuntimeException failure){return false;}};assertThrows(MinutesContracts.Failure.class,()->f.session.observe(observation));assertFalse(f.session.pending());f.session.retry();assertEquals(1,f.seen.size());assertFalse(f.session.send(()->{f.sends.incrementAndGet();return observation;}));assertEquals(0,f.sends.get());assertEquals(1,f.begins.get());}}
 @Test void expiredReconciliationObservationYieldsItsSlotForANewOriginalReceiptLookup()throws Exception{try(var f=new Fixture(true)){var observation=new ExternalOperationPort.PreparedObservation(){public boolean retainForLocalRetry(RuntimeException failure){return false;}};assertThrows(MinutesContracts.Failure.class,()->f.session.observe(observation));assertFalse(f.session.pending());f.session.retry();assertEquals(1,f.seen.size());assertEquals(0,f.begins.get());}}
 @Test void legacyOrTransientPreparationKeepsTheSameReceiptUntilRealAcknowledgement()throws Exception{try(var f=new Fixture(true)){var observation=new ExternalOperationPort.PreparedObservation(){};assertThrows(MinutesContracts.Failure.class,()->f.session.observe(observation));assertTrue(f.session.pending());f.fail.set(false);f.session.retry();assertFalse(f.session.pending());assertEquals(2,f.seen.size());assertSame(observation,f.seen.get(0));assertSame(observation,f.seen.get(1));assertEquals(0,f.begins.get());}}
 @Test void aBrokenLifetimeHookCannotSilentlyDiscardTheOnlyPendingReceipt()throws Exception{try(var f=new Fixture(true)){var observation=new ExternalOperationPort.PreparedObservation(){public boolean retainForLocalRetry(RuntimeException failure){throw new IllegalStateException("lifetime unavailable");}};assertThrows(MinutesContracts.Failure.class,()->f.session.observe(observation));assertTrue(f.session.pending());f.fail.set(false);f.session.retry();assertFalse(f.session.pending());assertEquals(2,f.seen.size());}}
}
